import type { DiffScrollSyncData } from '../types/previewMessaging';

export class DiffScrollSyncManager {

	readonly #previewId = Math.random().toString(36).slice(2, 10);
	readonly #onIncomingScroll: (line: number) => void;

	#syncData: DiffScrollSyncData;
	readonly #channel: BroadcastChannel;
	#ignoreIncomingScrollUntil = 0;

	constructor(sync: DiffScrollSyncData, onIncomingScroll: (line: number) => void) {
		this.#onIncomingScroll = onIncomingScroll;
		this.#syncData = sync;
		this.#channel = new BroadcastChannel(sync.channelName);
		this.#channel.onmessage = (event) => {
			const { line, sender } = event.data;
			if (sender === this.#previewId) {
				return;
			}
			if (typeof line !== 'number' || isNaN(line)) {
				return;
			}

			const mappedLine = translateLineWithMappings(line, this.#syncData.lineMappings);
			this.#ignoreIncomingScrollUntil = Date.now() + 100;
			this.#onIncomingScroll(mappedLine);
		};
	}

	update(sync: DiffScrollSyncData): void {
		this.#syncData = sync;
	}

	broadcastScroll(line: number): void {
		if (!this.#channel || Date.now() < this.#ignoreIncomingScrollUntil) {
			return;
		}
		this.#channel.postMessage({ line, sender: this.#previewId });
	}
}

function translateLineWithMappings(line: number, mappings: readonly number[] | undefined): number {
	if (!mappings?.length) {
		return line;
	}
	const sourceLine = Math.floor(line);
	const progress = line - sourceLine;
	const mappedLine = mappings[sourceLine] ?? line;
	if (progress <= 0) {
		return Math.max(0, mappedLine);
	}
	const nextMappedLine = mappings[sourceLine + 1];
	if (typeof nextMappedLine !== 'number') {
		return Math.max(0, mappedLine + progress);
	}
	return Math.max(0, mappedLine + ((nextMappedLine - mappedLine) * progress));
}

import type { AnyNode, AnyNodeId, ElevatorNode } from '../../schema'
import type { ElevatorInteractiveState } from '../../store/use-interactive'
import { resolveElevatorServiceLevels } from './elevator-service'

type ElevatorRuntimeMap = Record<AnyNodeId, ElevatorInteractiveState>

type ResolveElevatorDispatchTargetArgs = {
  elevators: ElevatorRuntimeMap
  levelId: AnyNodeId
  nodes: Record<string, AnyNode>
  requestedElevatorId: AnyNodeId
}

function getRuntimeLevelId(runtime: ElevatorInteractiveState | undefined, elevator: ElevatorNode) {
  return runtime?.currentLevelId ?? elevator.defaultLevelId ?? elevator.fromLevelId ?? null
}

function scoreDispatchCandidate({
  elevator,
  elevators,
  levelId,
  nodes,
}: {
  elevator: ElevatorNode
  elevators: ElevatorRuntimeMap
  levelId: AnyNodeId
  nodes: Record<string, AnyNode>
}) {
  if ((elevator.disabledLevelIds ?? []).includes(levelId)) return null
  if ((elevator.serviceOnlyLevelIds ?? []).includes(levelId)) return null

  const serviceLevels = resolveElevatorServiceLevels(elevator, nodes)
  const targetIndex = serviceLevels.findIndex((level) => level.id === levelId)
  if (targetIndex < 0) return null

  const runtime = elevators[elevator.id as AnyNodeId]
  const runtimeLevelId = getRuntimeLevelId(runtime, elevator)
  const currentIndex = runtimeLevelId
    ? serviceLevels.findIndex((level) => level.id === runtimeLevelId)
    : -1
  const resolvedCurrentIndex = currentIndex >= 0 ? currentIndex : 0
  const distance = Math.abs(targetIndex - resolvedCurrentIndex)
  const queuePenalty = (runtime?.queue.length ?? 0) * 2 + (runtime?.targetLevelId ? 1 : 0)
  const motionPenalty = runtime?.phase === 'moving' || runtime?.phase === 'closing' ? 0.5 : 0
  const openPenalty = runtime?.phase === 'open' || runtime?.phase === 'opening' ? 0.2 : 0

  return distance + queuePenalty + motionPenalty + openPenalty
}

export function resolveElevatorDispatchTarget({
  elevators,
  levelId,
  nodes,
  requestedElevatorId,
}: ResolveElevatorDispatchTargetArgs): AnyNodeId {
  const requestedElevator = nodes[requestedElevatorId]
  if (!(requestedElevator?.type === 'elevator' && requestedElevator.parentId)) {
    return requestedElevatorId
  }

  const building = nodes[requestedElevator.parentId as AnyNodeId]
  if (building?.type !== 'building') {
    return requestedElevatorId
  }

  let bestElevatorId: AnyNodeId | null = null
  let bestScore = Number.POSITIVE_INFINITY

  for (const childId of building.children) {
    const candidate = nodes[childId as AnyNodeId]
    if (!(candidate?.type === 'elevator' && candidate.visible !== false)) continue

    const score = scoreDispatchCandidate({
      elevator: candidate,
      elevators,
      levelId,
      nodes,
    })
    if (score === null) continue

    const tieBreaker = candidate.id === requestedElevatorId ? -0.01 : 0
    const finalScore = score + tieBreaker
    if (finalScore < bestScore) {
      bestScore = finalScore
      bestElevatorId = candidate.id as AnyNodeId
    }
  }

  return bestElevatorId ?? requestedElevatorId
}

import { describe, expect, test } from 'bun:test'
import type { AnyNode } from '../../schema'
import { BuildingNode, LevelNode, SlabNode, StairNode, StairSegmentNode } from '../../schema'
import {
  getNodesWithLiveStairOpeningInputs,
  hasLiveStairOpeningInputs,
} from './stair-opening-preview'
import { syncAutoStairOpenings } from './stair-opening-sync'

describe('stair opening previews', () => {
  test('computes auto openings from live stair transforms', () => {
    const building = BuildingNode.parse({ name: 'Building' })
    const ground = LevelNode.parse({ name: 'Ground', level: 0, parentId: building.id })
    const upper = LevelNode.parse({ name: 'Upper', level: 1, parentId: building.id })
    const slab = SlabNode.parse({
      name: 'Upper Slab',
      parentId: upper.id,
      polygon: [
        [0, 0],
        [5, 0],
        [5, 4],
        [0, 4],
      ],
    })
    const segment = StairSegmentNode.parse({
      parentId: 'stair_live',
      width: 1,
      length: 3,
      height: 2.5,
      stepCount: 12,
    })
    const stair = StairNode.parse({
      id: 'stair_live',
      name: 'Live Stair',
      parentId: ground.id,
      position: [1, 0, 0.2],
      stairType: 'straight',
      fromLevelId: ground.id,
      toLevelId: upper.id,
      slabOpeningMode: 'destination',
      children: [segment.id],
    })
    const nodes = Object.fromEntries(
      [building, ground, upper, slab, stair, { ...segment, parentId: stair.id }].map((node) => [
        node.id,
        node,
      ]),
    ) as Record<string, AnyNode>
    const liveTransforms = new Map([
      [stair.id, { position: [3, 0, 0.2] as [number, number, number], rotation: 0 }],
    ])
    const liveOverrides = new Map<string, Record<string, unknown>>()

    expect(hasLiveStairOpeningInputs(nodes, liveTransforms, liveOverrides, new Set())).toBe(true)

    const previewNodes = getNodesWithLiveStairOpeningInputs(
      nodes,
      liveTransforms,
      liveOverrides,
      new Set(),
    )
    const updates = syncAutoStairOpenings(previewNodes)
    const hole = updates.find((update) => update.id === slab.id)?.data.holes?.[0]

    expect(hole).toBeDefined()
    expect(Math.max(...hole!.map(([x]) => x))).toBeGreaterThan(3.4)
  })

  test('ignores its own live surface overrides as preview inputs', () => {
    const slab = SlabNode.parse({
      polygon: [
        [0, 0],
        [4, 0],
        [4, 4],
        [0, 4],
      ],
    })
    const nodes = { [slab.id]: slab } as Record<string, AnyNode>
    const liveOverrides = new Map<string, Record<string, unknown>>([
      [
        slab.id,
        {
          holes: [
            [
              [1, 1],
              [2, 1],
              [2, 2],
              [1, 2],
            ],
          ],
        },
      ],
    ])

    expect(hasLiveStairOpeningInputs(nodes, new Map(), liveOverrides, new Set([slab.id]))).toBe(
      false,
    )
  })
})

import type { AnyNode, AnyNodeId, CeilingNode, SlabNode } from '../../schema'
import useLiveNodeOverrides, { type LiveNodeOverrides } from '../../store/use-live-node-overrides'
import type { LiveTransform } from '../../store/use-live-transforms'
import useScene from '../../store/use-scene'

type SurfaceOpeningUpdate = {
  id: AnyNodeId
  data: Partial<SlabNode | CeilingNode>
}

const SURFACE_OPENING_FIELDS = ['holes', 'holeMetadata'] as const

function isSurface(node: AnyNode | undefined): node is SlabNode | CeilingNode {
  return node?.type === 'slab' || node?.type === 'ceiling'
}

function isStairOpeningInputNode(node: AnyNode | undefined) {
  return node?.type === 'stair' || node?.type === 'stair-segment'
}

function omitPreviewSurfaceFields(override: LiveNodeOverrides) {
  const next = { ...override }
  for (const field of SURFACE_OPENING_FIELDS) {
    delete next[field]
  }
  return next
}

export function hasLiveStairOpeningInputs(
  nodes: Record<string, AnyNode>,
  liveTransforms: ReadonlyMap<string, LiveTransform>,
  liveOverrides: ReadonlyMap<string, LiveNodeOverrides>,
  previewSurfaceIds: ReadonlySet<string>,
) {
  for (const nodeId of liveTransforms.keys()) {
    if (nodes[nodeId]?.type === 'stair') return true
  }

  for (const [nodeId, override] of liveOverrides) {
    if (previewSurfaceIds.has(nodeId)) continue
    if (Object.keys(override).length > 0 && isStairOpeningInputNode(nodes[nodeId])) return true
  }

  return false
}

export function getNodesWithLiveStairOpeningInputs(
  nodes: Record<string, AnyNode>,
  liveTransforms: ReadonlyMap<string, LiveTransform>,
  liveOverrides: ReadonlyMap<string, LiveNodeOverrides>,
  previewSurfaceIds: ReadonlySet<string>,
) {
  const nextNodes: Record<string, AnyNode> = { ...nodes }

  for (const [nodeId, override] of liveOverrides) {
    const node = nextNodes[nodeId]
    if (!node) continue

    const values = previewSurfaceIds.has(nodeId) ? omitPreviewSurfaceFields(override) : override
    if (Object.keys(values).length === 0) continue
    nextNodes[nodeId] = { ...node, ...values } as AnyNode
  }

  for (const [nodeId, transform] of liveTransforms) {
    const node = nextNodes[nodeId]
    if (node?.type !== 'stair') continue
    nextNodes[nodeId] = {
      ...node,
      position: transform.position,
      rotation: transform.rotation,
    }
  }

  return nextNodes
}

export function createSurfaceOpeningPreviewController() {
  const previewSurfaceIds = new Set<AnyNodeId>()

  const clearSurface = (id: AnyNodeId) => {
    useLiveNodeOverrides.getState().clearFields(id, SURFACE_OPENING_FIELDS)
    useScene.getState().markDirty(id)
  }

  return {
    previewSurfaceIds,
    apply(updates: SurfaceOpeningUpdate[]) {
      const scene = useScene.getState()
      const nextSurfaceIds = new Set<AnyNodeId>()

      for (const update of updates) {
        const node = scene.nodes[update.id]
        if (!isSurface(node)) continue
        if (!('holes' in update.data || 'holeMetadata' in update.data)) continue

        nextSurfaceIds.add(update.id)
        useLiveNodeOverrides.getState().set(update.id, {
          holes: update.data.holes ?? [],
          holeMetadata: update.data.holeMetadata ?? [],
        })
        scene.markDirty(update.id)
      }

      for (const id of previewSurfaceIds) {
        if (!nextSurfaceIds.has(id)) clearSurface(id)
      }

      previewSurfaceIds.clear()
      for (const id of nextSurfaceIds) {
        previewSurfaceIds.add(id)
      }
    },
    clear() {
      for (const id of previewSurfaceIds) {
        clearSurface(id)
      }
      previewSurfaceIds.clear()
    },
  }
}
